<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#172033;font-size:12px}header{border-bottom:2px solid #4f46e5;padding-bottom:18px}h1{font-size:28px;margin:0}table{border-collapse:collapse;width:100%;margin-top:28px}th,td{padding:10px;border-bottom:1px solid #ddd;text-align:left}.right{text-align:right}.totals{margin-left:auto;margin-top:20px;width:45%}.totals div{display:flex;justify-content:space-between;padding:5px}.grand{font-weight:bold;font-size:16px;border-top:2px solid #172033}</style></head><body><header><h1>INVOICE {{ $invoice->invoice_number }}</h1><p>Ikira Company</p></header><p><strong>Bill to:</strong> {{ $invoice->company->billing_name ?: $invoice->company->name }}<br>{{ $invoice->company->billing_address }}</p><p>Issued: {{ $invoice->issue_date->format('F j, Y') }}<br>Due: {{ $invoice->due_date->format('F j, Y') }}</p><table><thead><tr><th>Description</th><th>Quantity</th><th class="right">Amount</th></tr></thead><tbody>@foreach($invoice->items as $item)<tr><td>{{ $item->description }}</td><td>{{ $item->quantity }}</td><td class="right">{{ $invoice->currency }} {{ number_format($item->total,2) }}</td></tr>@endforeach</tbody></table><div class="totals"><div><span>Subtotal</span><span>{{ number_format($invoice->subtotal,2) }}</span></div><div><span>Discount</span><span>-{{ number_format($invoice->discount,2) }}</span></div><div class="grand"><span>Total</span><span>{{ $invoice->currency }} {{ number_format($invoice->total,2) }}</span></div><div><span>Paid</span><span>{{ number_format($invoice->paidAmount(),2) }}</span></div><div><span>Remaining</span><span>{{ number_format($invoice->remainingAmount(),2) }}</span></div></div>@if($invoice->payment_instructions)<h3>Payment instructions</h3><p>{{ $invoice->payment_instructions }}</p>@endif@if($invoice->public_notes)<h3>Notes</h3><p>{{ $invoice->public_notes }}</p>@endif</body></html>
